<section class="os-budget-section"><h2>Anotações</h2>
<?php if ($osCanMutate) { ?><form id="formAnotacao" method="post" action="<?= site_url('os/adicionarAnotacao') ?>" data-os-ajax data-os-message="Anotação adicionada."><input type="hidden" name="os_id" value="<?= (int) $result->idOs ?>"><label for="note-text">Nova anotação</label><textarea id="note-text" name="anotacao" required rows="3"></textarea><button type="submit" class="btn btn-primary">Adicionar anotação</button></form><?php } ?>
<?php foreach ($anotacoes as $note) { ?><article class="os-note"><time><?= html_escape(date('d/m/Y H:i', strtotime($note->data_hora))) ?></time><p><?= nl2br(html_escape($note->anotacao)) ?></p><?php if ($osCanMutate) { ?><form action="<?= site_url('os/excluirAnotacao') ?>" method="post" data-os-ajax data-os-confirm="Remover esta anotação?" data-os-message="Anotação removida."><input type="hidden" name="idOs" value="<?= (int) $result->idOs ?>"><input type="hidden" name="idAnotacao" value="<?= (int) $note->idAnotacoes ?>"><button type="submit" class="btn btn-danger btn-small">Remover anotação</button></form><?php } ?></article><?php } ?>
<?php if (! $anotacoes) { ?><p>Nenhuma anotação cadastrada.</p><?php } ?></section>
<section class="os-budget-section"><h2>Anexos</h2>
<?php if ($osCanMutate) { ?><form id="formAnexos" method="post" action="<?= site_url('os/anexar') ?>" enctype="multipart/form-data" data-os-ajax data-os-message="Anexos adicionados."><input type="hidden" name="idOsServico" value="<?= (int) $result->idOs ?>"><label for="attachment-files">Selecionar arquivos</label><input id="attachment-files" name="userfile[]" type="file" multiple required><button type="submit" class="btn btn-primary">Anexar arquivos</button></form><?php } ?>
<ul class="os-attachments"><?php foreach ($anexos as $attachment) { ?><li><a href="<?= site_url('os/downloadanexo/' . (int) $attachment->idAnexos) ?>"><?= html_escape($attachment->anexo) ?></a><?php if ($attachment->thumb) { ?><details class="os-attachment-preview"><summary>Ver prévia da imagem</summary><img loading="lazy" src="<?= html_escape($attachment->url . '/thumbs/' . rawurlencode($attachment->thumb)) ?>" alt="Prévia de <?= html_escape($attachment->anexo) ?>"></details><?php } ?><?php if ($osCanMutate) { ?><form method="post" action="<?= site_url('os/excluirAnexo/' . (int) $attachment->idAnexos) ?>" data-os-ajax data-os-confirm="Remover este anexo?" data-os-message="Anexo removido."><input type="hidden" name="idOs" value="<?= (int) $result->idOs ?>"><button type="submit" class="btn btn-danger btn-small">Remover anexo</button></form><?php } ?></li><?php } ?></ul>
<?php if (! $anexos) { ?><p>Nenhum anexo cadastrado.</p><?php } ?></section>
